import { test, expect } from '@playwright/test';

test.describe('Payment Timeout Error Redirection', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/payment');
  });

  test('should redirect to error page when payment times out', async ({ page }) => {
    // Intercept the payment API call
    await page.route('**/api/payment/process', (route) => {
      route.abort('timedout');
    });

    // Click the pay button
    const payButton = page.getByRole('button', { name: /pay/i });
    await payButton.click();

    // Wait for the timeout error to be processed
    await page.waitForTimeout(1000);

    // Verify error message is displayed
    const errorMessage = page.getByText(/payment timed out/i);
    await expect(errorMessage).toBeVisible();

    // Verify user is redirected to error page
    await expect(page).toHaveURL(/.*\/error/);

    // Verify error page title
    const errorTitle = page.getByRole('heading', { name: /error/i });
    await expect(errorTitle).toBeVisible();

    // Verify error details
    const errorDetails = page.getByText(/payment failed/i);
    await expect(errorDetails).toBeVisible();
  });

  test('should handle multiple payment timeouts and display correct error state', async ({ page }) => {
    // Intercept the payment API call and abort it
    await page.route('**/api/payment/process', (route) => {
      route.abort('timedout');
    });

    // Click the pay button
    const payButton = page.getByRole('button', { name: /pay/i });
    await payButton.click();

    // Wait for the first timeout
    await page.waitForTimeout(1500);

    // Verify first error message
    const errorMessage = page.getByText(/payment timed out/i);
    await expect(errorMessage).toBeVisible();

    // Verify user is on error page
    await expect(page).toHaveURL(/.*\/error/);

    // Verify error details
    const errorDetails = page.getByText(/payment failed/i);
    await expect(errorDetails).toBeVisible();

    // Attempt to retry payment
    const retryButton = page.getByRole('button', { name: /retry/i });
    await retryButton.click();

    // Intercept the retry request
    await page.route('**/api/payment/process', (route) => {
      route.abort('timedout');
    });

    // Wait for the second timeout
    await page.waitForTimeout(1500);

    // Verify retry error message
    const retryErrorMessage = page.getByText(/payment timed out again/i);
    await expect(retryErrorMessage).toBeVisible();

    // Verify error state persists
    await expect(page).toHaveURL(/.*\/error/);
  });
});
